<?php
$pdo=db();
$year=filter_var($_GET['year']??date('Y'),FILTER_VALIDATE_INT);
if(!$year||$year<2000||$year>2100)$year=(int)date('Y');
$start=sprintf('%04d-01-01',$year);$end=sprintf('%04d-01-01',$year+1);
$currencies=['USD','ZiG'];$fees=['USD'=>0.0,'ZiG'=>0.0];$expenses=['USD'=>0.0,'ZiG'=>0.0];$payroll=['USD'=>0.0,'ZiG'=>0.0];$costsByCategory=[];
$feeStmt=$pdo->prepare("SELECT e.currency,SUM(CASE WHEN e.transaction_type='Payment' THEN e.amount WHEN original.transaction_type='Payment' AND e.reverses_id IS NOT NULL THEN -e.amount ELSE 0 END) AS net_received FROM fee_ledger e LEFT JOIN fee_ledger original ON original.id=e.reverses_id WHERE e.transaction_date>=:start AND e.transaction_date<:end AND (e.transaction_type='Payment' OR (e.reverses_id IS NOT NULL AND original.transaction_type='Payment')) GROUP BY e.currency");
$feeStmt->execute(['start'=>$start,'end'=>$end]);foreach($feeStmt->fetchAll() as $row)$fees[$row['currency']]=(float)$row['net_received'];
$expenseStmt=$pdo->prepare("SELECT currency,SUM(amount) AS paid_total FROM school_expenses WHERE status='Paid' AND paid_at>=:start AND paid_at<:end GROUP BY currency");
$expenseStmt->execute(['start'=>$start,'end'=>$end]);foreach($expenseStmt->fetchAll() as $row)$expenses[$row['currency']]=(float)$row['paid_total'];
$categoryStmt=$pdo->prepare("SELECT category,currency,SUM(amount) AS paid_total,COUNT(*) AS item_count FROM school_expenses WHERE status='Paid' AND paid_at>=:start AND paid_at<:end GROUP BY category,currency ORDER BY category,currency");
$categoryStmt->execute(['start'=>$start,'end'=>$end]);foreach($categoryStmt->fetchAll() as $row)$costsByCategory[$row['category']][$row['currency']]=$row;
$payrollStmt=$pdo->prepare("SELECT currency,SUM(net_pay) AS paid_total FROM (SELECT r.currency,l.id,l.base_salary+COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount WHEN i.item_type='Deduction' THEN -i.amount ELSE 0 END),0) AS net_pay FROM payroll_runs r JOIN payroll_lines l ON l.run_id=r.id LEFT JOIN payroll_line_items i ON i.payroll_line_id=l.id WHERE r.status='Paid' AND r.paid_at>=:start AND r.paid_at<:end GROUP BY r.currency,l.id,l.base_salary) paid_lines GROUP BY currency");
$payrollStmt->execute(['start'=>$start,'end'=>$end]);foreach($payrollStmt->fetchAll() as $row)$payroll[$row['currency']]=(float)$row['paid_total'];
?>
<?php if(in_array($user['role'],['Administrator','Head'],true)): ?><div class="settings-tabs"><a href="?page=reports&view=academic">Academic reports</a><a class="selected" href="?page=reports&view=finance">Finance report</a></div><?php endif; ?>
<div class="page-heading"><div><div class="eyebrow">SCHOOL FINANCE · <?= (int)$year ?></div><h1>Finance report</h1><p class="subheading">Annual cash recorded from fee payments, operating expenses and finalized payroll.</p></div><div class="page-actions"><form method="get" class="compact-form"><input type="hidden" name="page" value="reports"><input type="hidden" name="view" value="finance"><label>Year<select name="year"><?php for($y=(int)date('Y');$y>=((int)date('Y')-8);$y--): ?><option value="<?= $y ?>" <?= $year===$y?'selected':'' ?>><?= $y ?></option><?php endfor; ?></select></label><button class="outline-button">View year</button></form><a class="outline-button" href="?page=fees">Fee accounts</a><a class="outline-button" href="?page=expenses&year=<?= (int)$year ?>">Expenses</a></div></div>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Recorded cash by currency</h2><p>Fee reversals are deducted on their transaction date. Payroll and expenses are included only when marked paid.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Currency</th><th>Fee receipts, net</th><th>Operating expenses paid</th><th>Payroll paid</th><th>Fee receipts less recorded costs</th></tr></thead><tbody><?php foreach($currencies as $currency): $residual=$fees[$currency]-$expenses[$currency]-$payroll[$currency]; ?><tr><td><b><?= h($currency) ?></b></td><td><?= h($currency) ?> <?= number_format($fees[$currency],2) ?></td><td><?= h($currency) ?> <?= number_format($expenses[$currency],2) ?></td><td><?= h($currency) ?> <?= number_format($payroll[$currency],2) ?></td><td><b><?= h($currency) ?> <?= number_format($residual,2) ?></b></td></tr><?php endforeach; ?></tbody></table></div><p class="privacy-note">This is not a bank balance or full profit-and-loss statement. It excludes non-fee income, unpaid expenses, payroll not marked paid, and other cash movements not recorded in Mavambo.</p></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Paid operating expenses by category</h2><p>Payment date falls within <?= (int)$year ?> · USD and ZiG stay separate</p></div><a class="text-button" href="actions/expense_export.php?year=<?= (int)$year ?>&status=Paid">Download expense details →</a></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Category</th><th>USD</th><th>ZiG</th><th>USD entries</th><th>ZiG entries</th></tr></thead><tbody><?php foreach($costsByCategory as $category=>$byCurrency): $usd=$byCurrency['USD']['paid_total']??0;$zig=$byCurrency['ZiG']['paid_total']??0; ?><tr><td><?= h($category) ?></td><td><?= number_format((float)$usd,2) ?></td><td><?= number_format((float)$zig,2) ?></td><td><?= (int)($byCurrency['USD']['item_count']??0) ?></td><td><?= (int)($byCurrency['ZiG']['item_count']??0) ?></td></tr><?php endforeach; if(!$costsByCategory): ?><tr><td colspan="5" class="empty-cell">No operating expenses were marked paid in this year.</td></tr><?php endif; ?></tbody></table></div></section>
